// Helper: get personas for a specific job group (e.g., '01')
function getPersonasByJobGroup(jobGroup) {
  return OCEAN_JOB_PERSONAS.filter(p => p.jobGroup === jobGroup);
}

// Helper: get job persona by code and job group
function getJobPersona(code, jobGroup) {
  return OCEAN_JOB_PERSONAS.find(p => p.code === code && p.jobGroup === jobGroup);
}

// Helper: get master persona by code
function getMasterPersona(code) {
  return OCEAN_MASTER_PERSONAS.find(p => p.code === code);
}

